import re, sys
t = open("skills/sprint/SKILL.md", encoding="utf-8").read()
sec = re.search(r"^## plan.*?(?=^## run)", t, re.S | re.M).group(0)
bad = []
for line in sec.splitlines():
    if not re.match(r"\d+\. ", line):
        continue
    for span in re.findall(r"`([^`]*)`", line):
        if re.match(r"python3 \S*backlog\.py (set|start|new)\b", span) and "--commit" not in span and "git commit" not in line:
            bad.append(span[-60:])
print(bad, file=sys.stderr)
sys.exit(1 if bad else 0)
